import React, { useState, useEffect } from 'react';
import VMList from './components/VMList';
import VMConsole from './components/VMConsole';
import VMMetrics from './components/VMMetrics';

function App() {
  const [selectedVM, setSelectedVM] = useState(null);
  const [vms, setVMs] = useState([]);
  const [telemetry, setTelemetry] = useState({});
  const [currentPage, setCurrentPage] = useState('HOME');

  useEffect(() => {
    fetchVMs();

    // Connect to telemetry WebSocket
    const ws = new WebSocket('ws://localhost:8080/ws/telemetry');
    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === 'metrics') {
        setTelemetry(prev => ({
          ...prev,
          [msg.vmId]: {
            cpuUsage: msg.cpuUsage,
            memoryUsage: msg.memoryUsage,
            diskUsage: msg.diskUsage
          }
        }));
      }
    };

    return () => ws.close();
  }, []);

  const fetchVMs = async () => {
    try {
      const response = await fetch('/api/vm/list');
      const data = await response.json();
      setVMs(data);
    } catch (error) {
      console.error('Failed to fetch VMs:', error);
    }
  };

  const createVM = async (vmData) => {
    try {
      const response = await fetch('/api/vm/create', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(vmData)
      });
      if (response.ok) {
        fetchVMs();
      }
    } catch (error) {
      console.error('Failed to create VM:', error);
    }
  };

  const startVM = async (id) => {
    try {
      await fetch(`/api/vm/${id}/start`, { method: 'POST' });
      fetchVMs();
    } catch (error) {
      console.error('Failed to start VM:', error);
    }
  };

  const stopVM = async (id) => {
    try {
      await fetch(`/api/vm/${id}/stop`, { method: 'POST' });
      fetchVMs();
    } catch (error) {
      console.error('Failed to stop VM:', error);
    }
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'HOME':
        return (
          <div>
            <h2 className="text-2xl font-bold text-white mb-6">Dashboard</h2>
            <p className="text-gray-300">Welcome to Vellum, your hypervisor management platform.</p>
          </div>
        );
      case 'VM':
        return (
          <div>
            <VMList
              vms={vms}
              onSelect={setSelectedVM}
              onCreate={createVM}
              onStart={startVM}
              onStop={stopVM}
            />
            {selectedVM && <VMMetrics vmId={selectedVM} metrics={telemetry[selectedVM]} />}
            {selectedVM && <VMConsole vmId={selectedVM} />}
          </div>
        );
      case 'LOG':
        return <div className="text-white"><h2 className="text-2xl font-bold mb-4">Logs</h2><p className="text-gray-300">System logs will appear here.</p></div>;
      case 'MORE':
        return <div className="text-white"><h2 className="text-2xl font-bold mb-4">More Options</h2><p className="text-gray-300">Additional features coming soon.</p></div>;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-black" style={{ color: '#e6e2d7' }}>
      <div className="flex flex-col h-screen">
        <div className="flex items-center justify-between px-8 py-4 border-b border-gray-700">
          <img src="/logo.png" alt="Vellum" className="h-16" />
          <h1 className="text-4xl font-bold tracking-widest absolute left-1/2 transform -translate-x-1/2">VELLUM</h1>
          <div></div>
        </div>

        <div className="flex flex-1 gap-6 p-6">
          <nav className="w-48 border rounded-2xl p-6 h-fit" style={{ borderColor: '#e6e2d7' }}>
            <ul className="space-y-6 text-2xl font-bold">
              <li>
                <button
                  onClick={() => setCurrentPage('HOME')}
                  className={`w-full text-left ${currentPage === 'HOME' ? '' : 'text-gray-500 hover:opacity-100'}`}
                  style={{ color: currentPage === 'HOME' ? '#e6e2d7' : '#888888' }}
                >
                  HOME
                </button>
              </li>
              <li>
                <button
                  onClick={() => setCurrentPage('VM')}
                  className={`w-full text-left ${currentPage === 'VM' ? '' : 'text-gray-500 hover:opacity-100'}`}
                  style={{ color: currentPage === 'VM' ? '#e6e2d7' : '#888888' }}
                >
                  VM
                </button>
              </li>
              <li>
                <button
                  onClick={() => setCurrentPage('LOG')}
                  className={`w-full text-left ${currentPage === 'LOG' ? '' : 'text-gray-500 hover:opacity-100'}`}
                  style={{ color: currentPage === 'LOG' ? '#e6e2d7' : '#888888' }}
                >
                  LOG
                </button>
              </li>
              <li>
                <button
                  onClick={() => setCurrentPage('MORE')}
                  className={`w-full text-left ${currentPage === 'MORE' ? '' : 'text-gray-500 hover:opacity-100'}`}
                  style={{ color: currentPage === 'MORE' ? '#e6e2d7' : '#888888' }}
                >
                  MORE
                </button>
              </li>
            </ul>
          </nav>

          <div className="flex-1 border rounded-2xl p-8" style={{ borderColor: '#e6e2d7' }}>
            {renderContent()}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
